		return 1
	key = ''.join(map(str, arr[:size]))
	if dp[key]:
		return dp[key]
	output = function(arr, size-1, dp)
	key = ''.join(map(str, arr[:size-1]))
	dp[key] = output
	if (arr[size-2]*10 + arr[size-1]) <= 26:
		output += function(arr, size-2, dp)
