def function(arr,s,n,dp):
	if s == 0:
		return 0
	if n == 0 and s!= 0:
		return s
	if dp[n][s] != 0:
		return dp[n][s]
	if arr[n-1] <= s:
		dp[n][s] = max(arr[n-1], function(arr,s-arr[n-1],n-1,dp), function(arr,s,n-1,dp))
		return dp[n][s]
	else:
		dp[n][s] = function(arr,s,n-1,dp)
		return dp[n][s]


